func test_exasol_TestExasol_test_show_tables(self *Case, a Args) Value {
	self.L(1004).ValidateAll("SELECT TABLE_NAME FROM SYS.EXA_ALL_TABLES WHERE TABLE_SCHEMA = 'TEST'", Kw("read", NewDict("mysql", "SHOW TABLES FROM test")), Kw("write", NewDict("exasol", "SELECT TABLE_NAME FROM SYS.EXA_ALL_TABLES WHERE TABLE_SCHEMA = 'TEST'")))
	self.L(1011).ValidateAll("SELECT TABLE_NAME FROM SYS.EXA_ALL_TABLES WHERE TABLE_SCHEMA = CURRENT_SCHEMA", Kw("read", NewDict("mysql", "SHOW TABLES")), Kw("write", NewDict("exasol", "SELECT TABLE_NAME FROM SYS.EXA_ALL_TABLES WHERE TABLE_SCHEMA = CURRENT_SCHEMA")))
	return nil
}

func test_exasol_TestExasol_test_show_databases(self *Case, a Args) Value {
	self.L(1020).ValidateAll("SELECT SCHEMA_NAME FROM SYS.EXA_SCHEMAS", Kw("read", NewDict("mysql", "SHOW DATABASES")), Kw("write", NewDict("exasol", "SELECT SCHEMA_NAME FROM SYS.EXA_SCHEMAS")))
	self.L(1025).ValidateAll("SELECT SCHEMA_NAME FROM SYS.EXA_SCHEMAS", Kw("read", NewDict("mysql", "SHOW SCHEMAS")), Kw("write", NewDict("exasol", "SELECT SCHEMA_NAME FROM SYS.EXA_SCHEMAS")))
	return nil
}

func test_exasol_TestExasol_test_group_by_alias_local(self *Case, a Args) Value {
	self.L(1033).ValidateAll("SELECT city, COUNT(*) AS cnt FROM t GROUP BY LOCAL.cnt", Kw("read", NewDict("mysql", "SELECT city, COUNT(*) AS cnt FROM t GROUP BY cnt")), Kw("write", NewDict("exasol", "SELECT city, COUNT(*) AS cnt FROM t GROUP BY LOCAL.cnt")))
	self.L(1039).ValidateAll("SELECT YEAR(TO_DATE(a_date)) AS a_year FROM t GROUP BY LOCAL.a_year", Kw("read", NewDict("mysql", "SELECT YEAR(a_date) AS a_year FROM t GROUP BY a_year")), Kw("write", NewDict("exasol", "SELECT YEAR(TO_DATE(a_date)) AS a_year FROM t GROUP BY LOCAL.a_year")))
	self.L(1045).ValidateAll("SELECT city, COUNT(*) FROM t GROUP BY city", Kw("read", NewDict("mysql", "SELECT city, COUNT(*) FROM t GROUP BY city")), Kw("write", NewDict("exasol", "SELECT city, COUNT(*) FROM t GROUP BY city")))
	self.L(1051).ValidateAll("SELECT COUNT(*) AS cnt FROM t HAVING LOCAL.cnt > 1", Kw("read", NewDict("mysql", "SELECT COUNT(*) AS cnt FROM t HAVING cnt > 1")), Kw("write", NewDict("exasol", "SELECT COUNT(*) AS cnt FROM t HAVING LOCAL.cnt > 1")))
	return nil
}
